use super::{native_appearance_layer_study as layer,native_appearance_inspection as a,world_depth::NativeDrawCell,world_map::{WorldCell,ViewProjection,PixelPoint},world_raster::{Raster,Blend},compositor::Canvas};
use std::{fs,path::{Path,PathBuf},collections::BTreeMap,sync::atomic::AtomicBool};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn sha(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
struct Fixed{root:PathBuf,pins:BTreeMap<String,Value>,used:std::cell::RefCell<BTreeMap<String,Value>>}
impl Fixed{
 fn new()->Self{let p:Value=serde_json::from_slice(&fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r439-appearance-snapshot.json")).unwrap()).unwrap();let root=PathBuf::from(p["candidate"]["root"].as_str().unwrap());let bytes=fs::read(root.join("manifest.json")).unwrap();assert_eq!(sha(&bytes),p["candidate"]["manifest_sha256"].as_str().unwrap().to_ascii_lowercase());let m:Value=serde_json::from_slice(&bytes).unwrap();Self{root,pins:m["files"].as_array().unwrap().iter().map(|v|(v["path"].as_str().unwrap().to_string(),v.clone())).collect(),used:Default::default()}}
 fn bytes(&self,name:&str)->Vec<u8>{let p=&self.pins[name];let bytes=fs::read(self.root.join(name)).unwrap();assert_eq!(bytes.len()as u64,p["bytes"].as_u64().unwrap());assert_eq!(sha(&bytes),p["sha256"].as_str().unwrap().to_ascii_lowercase());self.used.borrow_mut().insert(name.to_owned(),p.clone());bytes}
 fn asset(&self,name:&str,bank:u32,hit:&Value)->layer::Asset{assert_eq!(hit["member"],name);let bytes=self.bytes(&format!("resources/{name}"));assert_eq!(sha(&bytes),hit["sha256"].as_str().unwrap().to_ascii_lowercase());assert_eq!(bytes.len()as u64,hit["bytes"].as_u64().unwrap());let digest=Sha256::digest(&bytes).into();layer::Asset::new(name.to_owned(),bank,&bytes,digest,hit["frame_count"].as_u64().unwrap()as usize).unwrap()}
}
fn inputs()->layer::Inputs{layer::Inputs{draw_branch_reached:Some(true),actor_flags:Some(0),layer_flags:Some(0),base_shadow_route:Some(true),all_layer_pointers_present:Some(true)}}
fn write_png(path:&Path,rgba:&[u8],width:u32,height:u32)->Value{let mut enc=png::Encoder::new(fs::File::create(path).unwrap(),width,height);enc.set_color(png::ColorType::Rgba);enc.set_depth(png::BitDepth::Eight);enc.write_header().unwrap().write_image_data(rgba).unwrap();json!({"path":path,"sha256":sha(&fs::read(path).unwrap()),"RGBA_sha256":sha(rgba),"dimensions":[width,height]})}
#[test]fn actual_attack47_shadow105_same_subframe_submission_depth_and_CPU(){
 let fixed=Fixed::new();let d=a::nad(&fixed.bytes("resources/appearance-dependencies.nad")).unwrap();let owners=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&owners[3];let trace:Value=serde_json::from_slice(&fixed.bytes("appearance-layer-trace.json")).unwrap();let dep:Value=serde_json::from_slice(&fixed.bytes("appearance-dependencies.json")).unwrap();let attrs=dep["rows"].as_array().unwrap().iter().find(|r|r["logical"]==734).unwrap()["opaque_attributes"].as_array().unwrap();for(key,raw)in[(101,"33343737"),(102,"35"),(105,"312036323630")]{assert!(attrs.iter().any(|v|v["key"]==key&&v["raw_body_hex"]==raw));}
 let graph=trace["layers"].as_array().unwrap();let hit=|kind:&str,name:&str|graph.iter().find(|v|v["base_logical"]==734&&v["kind"]==kind).unwrap()["hits"].as_array().unwrap().iter().find(|v|v["member"]==name).unwrap();
 let mut model=layer::Model::new(true,b,b,b.observed,56).unwrap();let mut rows=Vec::new();let mut images=Vec::new();let out=Path::new(env!("CARGO_MANIFEST_DIR")).join("target/r448-appearance-layer-cpu");fs::create_dir_all(&out).unwrap();let mut sheet=vec![0u8;1400*200*4];let mut isolated=vec![0u8;600*200*4];let mut fragment_ledger=Vec::new();let mut skip_cases=0;
 for heading in 0..8{let plan=a::plan(true,&d,b,b,b.observed,a::Kind::Attack,heading,128).unwrap();let bank=88+heading as u32;let body_name=format!("3476-{bank}.spr");let member=&d.members[&body_name];let bytes=fixed.bytes(&format!("resources/{body_name}"));let body=layer::Asset::new(body_name.clone(),bank,&bytes,member.sha256,member.frames as usize).unwrap();let shadow_name=format!("3477-{bank}.spr");let shadow=fixed.asset(&shadow_name,bank,hit("shadow",&shadow_name));let layer_name=format!("6260-{bank}.spr");let added=fixed.asset(&layer_name,bank,hit("catalog105_layer",&layer_name));
  for(column,index)in [1,2,3,4,5,6].iter().enumerate(){let catalog=plan.frames[*index].0;assert_eq!(catalog.image+heading as u32,bank);let list=model.submissions(b,b.observed,bank,catalog.subframe as usize,&body,&shadow,&added,inputs()).unwrap();let sample=model.render(b,b.observed,&list).unwrap();assert_eq!(sample.submission_order,["body","catalog105","shadow"]);assert!(!sample.renderer_ready&&!sample.native_framebuffer_parity_qualified);assert!(sample.fragment_count[0]>0&&sample.fragment_count[2]>0);
   let mut skip=inputs();skip.actor_flags=Some(2);let skipped=model.submissions(b,b.observed,bank,catalog.subframe as usize,&body,&shadow,&added,skip).unwrap();assert_eq!(skipped.iter().map(|s|s.kind).collect::<Vec<_>>(),["body","shadow"]);assert_eq!(skipped.iter().map(|s|s.flags).collect::<Vec<_>>(),[2,7]);assert!(model.render(b,b.observed,&skipped).is_err());skip_cases+=1;
   rows.push(json!({"heading":heading,"catalog_frame":index,"directed_bank":bank,"subframe":catalog.subframe,"submission_order":sample.submission_order,"reference_counts":sample.fragment_count,"members":[&body.name,&added.name,&shadow.name],"sha256":[sha(&bytes),format!("{:x}",Sha256::digest(fixed.bytes(&format!("resources/{layer_name}")))),format!("{:x}",Sha256::digest(fixed.bytes(&format!("resources/{shadow_name}"))))]}));
   if heading==0{for y in 0..200{sheet[(y*1400+column*200)*4..(y*1400+(column+1)*200)*4].copy_from_slice(&sample.canvas.rgba()[y*200*4..(y+1)*200*4]);}
    if column==0{let origin=NativeDrawCell::from_world(WorldCell{x:32724,y:32784}).unwrap();let view=ViewProjection{anchor_cell:WorldCell{x:32724,y:32784},anchor_pixel:PixelPoint{x:100,y:140}};let mut ordered=Vec::new();let mut sequence=0u64;
     for(column,s)in list.iter().enumerate(){assert!(!s.asset.sha256.iter().all(|v|*v==0));let mut canvas=Canvas::new(200,200).unwrap();let mut raster=Raster::new(view,&canvas);raster.sprite(origin,s.frame,0,Blend::Over).unwrap();raster.paint(&mut canvas,&AtomicBool::new(false),0).unwrap();for y in 0..200{isolated[(y*600+column*200)*4..(y*600+(column+1)*200)*4].copy_from_slice(&canvas.rgba()[y*200*4..(y+1)*200*4]);}
      for(reference_index,r)in s.frame.fragments.as_ref().unwrap().references.iter().enumerate(){let cell=origin.fragment(*r).unwrap();let key=cell.overlay_key(r.depth,sequence);ordered.push((key,json!({"kind":s.kind,"half_x":cell.half_x,"y":cell.y,"depth":r.depth,"insertion":sequence,"block_id":r.block_id,"reference_index":reference_index})));sequence+=1;}
     }
     ordered.sort_by_key(|v|v.0);fragment_ledger=ordered.into_iter().map(|v|v.1).collect();assert!(!fragment_ledger.is_empty());
     // Independent literal native scan/depth/newest-first key and pixel
     // compositor; do not use Raster or NativeDrawKey for this oracle.
     let literal_key=|v:&Value|{let x=v["half_x"].as_i64().unwrap();let y=v["y"].as_i64().unwrap();(2*y-(x&!1),((x+1)&!1)+2*y,v["depth"].as_u64().unwrap(),std::cmp::Reverse(v["insertion"].as_u64().unwrap()))};
     let mut independent=fragment_ledger.clone();independent.sort_by_key(literal_key);assert_eq!(independent,fragment_ledger);
     let mut reference=Canvas::new(200,200).unwrap();reference.clear([18,25,35]);
     for v in &independent{let s=list.iter().find(|s|s.kind==v["kind"].as_str().unwrap()).unwrap();let source=s.frame.fragments.as_ref().unwrap();let mut rgba=[0u8;24*24*4];source.atlas[v["block_id"].as_u64().unwrap()as usize].write_rgba(&mut rgba);let(row,col,_,_)=literal_key(v);let x=i32::try_from(76+12*(col-98248)).unwrap();let y=i32::try_from(128+6*(row-32888)).unwrap();if s.kind=="shadow"{reference.blit_native_shadow_rgb555(&rgba,24,24,x,y).unwrap();}else{reference.blit_rgba(&rgba,24,24,x,y).unwrap();}}
     assert_eq!(reference.rgba(),sample.canvas.rgba(),"Actual body/105/shadow Raster equals independent original ordered-fragment CPU reference");
    }
   }
  }
  // Guards are checked before CPU mutation, not fabricated empty layers.
  for selector in 0..6{let mut input=inputs();match selector{0=>input.actor_flags=None,1=>input.layer_flags=None,2=>input.all_layer_pointers_present=None,3=>input.base_shadow_route=None,4=>input.actor_flags=Some(0x40),_=>input.draw_branch_reached=None};assert!(model.submissions(b,b.observed,bank,0,&body,&shadow,&added,input).is_err());}
  assert!(model.submissions(b,b.observed,bank+1,0,&body,&shadow,&added,inputs()).is_err());assert!(model.submissions(b,b.observed,bank,255,&body,&shadow,&added,inputs()).is_err());
  assert!(layer::Asset::new(body_name.clone(),bank,&bytes,[0;32],member.frames as usize).is_err());
  if heading==7{model.retire();assert!(model.submissions(b,b.observed,bank,0,&body,&shadow,&added,inputs()).is_err());}
 }
 // Seventh strip slot intentionally shows the rejected end-frame0 bank72 as
 // a blank scope marker; this branch does not manufacture88-frame0 for end0.
 // Crop to exactly the six qualified same-bank subframes.
 let mut cropped=vec![0u8;1200*200*4];for y in 0..200{cropped[y*1200*4..(y+1)*1200*4].copy_from_slice(&sheet[y*1400*4..(y*1400+1200)*4]);}
 images.push(write_png(&out.join("elf-attack47-body105-shadow-six-source-subframes.png"),&cropped,1200,200));images.push(write_png(&out.join("elf-attack47-body105-shadow-isolated-source-layers.png"),&isolated,600,200));
 model.retire();let mut wrong=b.clone();wrong.revision+=1;assert!(layer::Model::new(true,b,&wrong,b.observed,1).is_err());assert!(layer::Model::new(false,b,b,b.observed,1).is_err());let timed={let mut v=b.clone();v.cutoff=v.observed+1;v};assert!(layer::Model::new(true,&timed,&timed,timed.cutoff,1).is_err());
 fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("logs/continuation-20261003/r448-layer-details.json"),serde_json::to_vec_pretty(&json!({"state":"FINITE_CONDITIONAL_ORIGINAL_BODY_105_SHADOW_HALF_CELL_CPU","source":b.source,"object":b.object,"historical_class":b.class,"source_rows":rows,"neutral_CPU_samples":48,"bit2_skip_submission_cases":skip_cases,"paint_order_first_sample":fragment_ledger,"images":images,"input_pins":fixed.used.into_inner(),"conditional_inputs":{"draw_branch_reached":true,"actor_flags":0,"catalog105_flags":0,"base_shadow_route":true,"all105_pointers_present":true},"105_flags_actually_observed":false,"runtime_inputs_observed":false,"end0_bank72_layer_branch_qualified":false,"native_framebuffer_parity_qualified":false,"events_dispatched":false,"renderer_LOADED":false,"GUI":0})).unwrap()).unwrap();
}
